// ============================================================
//  Environment map (soft studio-sky for paint + chrome reflections)
// ============================================================
function makeEnvMap(renderer, opts = {}) {
  const scene = new THREE.Scene();
  const top = new THREE.Color(opts.top || 0x6fa8dc), hor = new THREE.Color(opts.horizon || 0xf3ead8), gnd = new THREE.Color(opts.ground || 0x5b5a52);
  const geo = new THREE.SphereGeometry(50, 48, 24);
  const cols = [];
  const p = geo.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const y = p.getY(i) / 50;
    const c = new THREE.Color();
    if (y > 0) c.copy(hor).lerp(top, Math.pow(y, 0.55));
    else c.copy(hor).lerp(gnd, Math.pow(-y, 0.35));
    cols.push(c.r, c.g, c.b);
  }
  geo.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
  scene.add(new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide })));
  // soft boxes for highlights
  const panel = (w, h, x, y, z, inten) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: new THREE.Color(inten, inten, inten * 0.97), side: THREE.DoubleSide }));
    m.position.set(x, y, z); m.lookAt(0, 0, 0); scene.add(m);
  };
  panel(40, 12, 0, 38, 10, 2.2);
  panel(14, 30, 42, 14, -8, 1.3);
  panel(14, 30, -42, 14, 8, 1.1);
  panel(60, 4, 0, 6, -46, 1.6);
  // dark band to give chrome contrast near horizon
  const band = new THREE.Mesh(new THREE.CylinderGeometry(48, 48, 3, 48, 1, true), new THREE.MeshBasicMaterial({ color: opts.band || 0x3c4a3a, side: THREE.BackSide }));
  band.position.y = -1.0; scene.add(band);
  const pm = new THREE.PMREMGenerator(renderer);
  const rt = pm.fromScene(scene, 0.035);
  pm.dispose();
  return rt.texture;
}

