      s.set(h.w * 0.85, 1, 1); p.set(h.x, y + 3.0, h.z);
      // awning faces toward road: offset along local +x/-x? use side facing nearest road
      const nr = World.roadIndex.nearest(h.x, h.z, 40);
      let ox = 0, oz = 0; if (nr) { const dx = nr.p.x - h.x, dz = nr.p.z - h.z, l = Math.hypot(dx, dz) || 1; ox = dx / l; oz = dz / l; }
      p.set(h.x + ox * (h.d / 2 + 0.7), y + 3.0, h.z + oz * (h.d / 2 + 0.7));
