    c.fillStyle = '#14213d'; c.font = 'bold 54px Arial'; c.textAlign = 'center'; c.fillText('BAYVIEW', w / 2, 118); c.font = 'bold 40px Arial'; c.fillText('GARAGE', w / 2, 168);
