  const sign = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.2, 0.3, 28), [new THREE.MeshLambertMaterial({ color: 0xe0186e }), new THREE.MeshLambertMaterial({ map: signTex }), new THREE.MeshLambertMaterial({ map: signTex })]);
  sign.rotation.z = Math.PI / 2; sign.rotation.y = Math.PI / 2; sign.position.set(gs.x - 14, gy + 9.4, gs.z + 9); sign.castShadow = true; scene.add(sign);

