  const capL = new THREE.Mesh(new THREE.ConeGeometry(1.9, 1.8, 12), new THREE.MeshLambertMaterial({ color: 0xd2343b })); capL.position.set(lh.x, ly + 20.5, lh.z); scene.add(capL);
