  const millCap = new THREE.Mesh(new THREE.ConeGeometry(2.2, 2.6, 8), new THREE.MeshLambertMaterial({ color: 0x9c3b30, flatShading: true })); millCap.position.set(fm.x, fy + 13.3, fm.z); scene.add(millCap);
  const blades = new THREE.Group(); blades.position.set(fm.x, fy + 11.5, fm.z + 2.2);
  for (let k = 0; k < 4; k++) { const b = new THREE.Mesh(new THREE.BoxGeometry(0.9, 6.5, 0.12), new THREE.MeshLambertMaterial({ color: 0xfaf6ee })); b.position.y = 3.3; const piv = new THREE.Group(); piv.rotation.z = k * Math.PI / 2; piv.add(b); blades.add(piv); }
  blades.userData.dynamic = true; scene.add(blades); World.anim.push((t) => { blades.rotation.z = t * 0.6; });
  World.colliders.add({ type: 'circle', x: fm.x, z: fm.z, r: 2.8 });
  const barn = addBox(scene, 12, 6, 9, fm.x + 22, fy - 0.3, fm.z - 8, 0xb23a32, 0.2, true);
  const barnRoof = new THREE.Mesh(roofG, new THREE.MeshLambertMaterial({ color: 0x5a5f66, flatShading: true }));
  barnRoof.scale.set(12.6, 4.2, 9 * 0.75); barnRoof.rotation.y = 0.2; barnRoof.position.set(fm.x + 22, fy - 0.3 + 6 + 1.05, fm.z - 8); scene.add(barnRoof);
  const silo = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.2, 11, 12), new THREE.MeshLambertMaterial({ color: 0xd9dde2 })); silo.position.set(fm.x + 32, fy + 5.2, fm.z - 2); silo.castShadow = true; scene.add(silo);
  const siloTop = new THREE.Mesh(new THREE.SphereGeometry(2.2, 12, 6, 0, TAU, 0, Math.PI / 2), new THREE.MeshLambertMaterial({ color: 0x8c96a0 })); siloTop.position.set(fm.x + 32, fy + 10.7, fm.z - 2); scene.add(siloTop);
  World.colliders.add({ type: 'circle', x: fm.x + 32, z: fm.z - 2, r: 2.4 });

  // --- Pier with a Ferris wheel
  const pz0 = 548, pz1 = 650, px = -118;
  const deckY = 2.4;
  const deck = new THREE.Mesh(new THREE.BoxGeometry(9, 0.5, pz1 - pz0), new THREE.MeshLambertMaterial({ color: 0xa4825c }));
  deck.position.set(px, deckY, (pz0 + pz1) / 2); deck.castShadow = true; deck.receiveShadow = true; scene.add(deck);
  for (let z = pz0 + 4; z < pz1; z += 8) for (const sx of [-4, 4]) { const post = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 8, 6), new THREE.MeshLambertMaterial({ color: 0x6d5038 })); post.position.set(px + sx, deckY - 4, z); scene.add(post); }
  const fw = new THREE.Group(); fw.position.set(px, deckY + 12, pz1 - 8);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(10, 0.3, 6, 32), new THREE.MeshLambertMaterial({ color: 0xffffff })); fw.add(rim);
  const wheelSpin = new THREE.Group(); fw.add(wheelSpin); wheelSpin.add(rim);
  const cabCols = [0xe0186e, 0x2a9d8f, 0xf4c430, 0x4f7cac, 0xf08a4b, 0x9b5de5];
  const cabs = [];
  for (let k = 0; k < 12; k++) {
    const a = k * TAU / 12;
    const sp = new THREE.Mesh(new THREE.BoxGeometry(0.18, 10, 0.18), new THREE.MeshLambertMaterial({ color: 0xffffff })); sp.position.set(Math.cos(a) * 5, Math.sin(a) * 5, 0); sp.rotation.z = a + Math.PI / 2; wheelSpin.add(sp);
    const cb = new THREE.Mesh(new THREE.BoxGeometry(1.6, 1.5, 1.6), new THREE.MeshLambertMaterial({ color: cabCols[k % 6] })); cb.userData.a = a; fw.add(cb); cabs.push(cb);
  }
  for (const sx of [-1, 1]) { const leg = new THREE.Mesh(new THREE.BoxGeometry(0.4, 13, 0.4), new THREE.MeshLambertMaterial({ color: 0xffffff })); leg.position.set(sx * 3.5, -6.2, 0); leg.rotation.z = sx * 0.28; fw.add(leg); }
  fw.rotation.y = Math.PI / 2; fw.userData.dynamic = true;
  scene.add(fw);
  World.anim.push((t) => { const r = t * 0.15; wheelSpin.rotation.z = r; cabs.forEach(c => { const a = c.userData.a + r; c.position.set(Math.cos(a) * 10, Math.sin(a) * 10 - 1, 0); }); });

  // --- Water tower in the desert + radio mast on the alpine ridge
  const wtw = { x: 420, z: 300 }; const wty = groundHeight(wtw.x, wtw.z);
  for (const [dx, dz] of [[-2, -2], [2, -2], [-2, 2], [2, 2]]) addBox(scene, 0.4, 12, 0.4, wtw.x + dx, wty, wtw.z + dz, 0x7a5c45, 0, false);
  const tank = new THREE.Mesh(new THREE.CylinderGeometry(4, 4, 5, 14), new THREE.MeshLambertMaterial({ color: 0xe0186e })); tank.position.set(wtw.x, wty + 14.5, wtw.z); tank.castShadow = true; scene.add(tank);
  const tankTop = new THREE.Mesh(new THREE.ConeGeometry(4.3, 2, 14), new THREE.MeshLambertMaterial({ color: 0xf2e6d0 })); tankTop.position.set(wtw.x, wty + 18, wtw.z); scene.add(tankTop);
  World.colliders.add({ type: 'circle', x: wtw.x, z: wtw.z, r: 3.2 });
  // lodge at mirror lake
