// ---------- Minimap base image ----------
function buildMinimapImage() {
  const S = 960, c = document.createElement('canvas'); c.width = S; c.height = S;
  const ctx = c.getContext('2d'); const img = ctx.createImageData(S, S);
  const N = W.n, col = World.terrainColors;
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const wx = -W.half + (x + 0.5) / S * 2 * W.half, wz = -W.half + (y + 0.5) / S * 2 * W.half;
    const i = clamp(Math.round((wx + W.half) / W.cell), 0, N - 1), j = clamp(Math.round((wz + W.half) / W.cell), 0, N - 1);
    const k = j * N + i; const h = World.H[k];
    let r = col[k * 3], g = col[k * 3 + 1], b = col[k * 3 + 2];
    const L = W.lake;
    if (h < 0 || (Math.hypot(wx - L.x, wz - L.z) < L.r + 4 && h < L.level)) { const dk = smooth(-12, -40, h); r = lerp(0.33, 0.1, dk); g = lerp(0.68, 0.36, dk); b = lerp(0.78, 0.62, dk); if (isleNear(wx, wz) && isleParams(wx, wz).bayou > 0.5) { r = 0.16; g = 0.24; b = 0.15; } } // (bayou pools: black water)
    // hill shading
    const hx = World.H[k + (i < N - 1 ? 1 : 0)] - World.H[k - (i > 0 ? 1 : 0)];
    const sh = clamp(1 - hx * 0.04, 0.75, 1.2);
    const o = (y * S + x) * 4;
    img.data[o] = clamp(Math.pow(r, 1 / 2.2) * 255 * sh, 0, 255); img.data[o + 1] = clamp(Math.pow(g, 1 / 2.2) * 255 * sh, 0, 255); img.data[o + 2] = clamp(Math.pow(b, 1 / 2.2) * 255 * sh, 0, 255); img.data[o + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const toPx = (v) => (v + W.half) / (2 * W.half) * S;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  for (const pass of [0, 1]) for (const r of World.roads) {
    ctx.beginPath();
    r.samples.forEach((p, i) => i ? ctx.lineTo(toPx(p.x), toPx(p.z)) : ctx.moveTo(toPx(p.x), toPx(p.z)));
    if (r.closed) ctx.closePath();
    ctx.strokeStyle = pass ? '#fff7e8' : 'rgba(20,33,61,0.55)'; ctx.lineWidth = pass ? 2.2 : 4.2; ctx.stroke();
  }
  drawDecksOnMinimap(ctx, toPx);
  ctx.beginPath(); ctx.arc(toPx(ATL.x), toPx(ATL.z), ATL.dome / (2 * W.half) * S, 0, TAU); ctx.fillStyle = 'rgba(160,245,255,0.35)'; ctx.fill(); ctx.strokeStyle = '#bff8ff'; ctx.lineWidth = 2; ctx.stroke(); // the Great Dome
  World.minimapImage = c;
}

// ---------- Wooden guardrails along exposed stretches of road ----------
function buildGuardrails(scene) {
  const posts = [], rails = [];
  for (const r of World.roads) {
    if (!['coast', 'pass', 'canyon', 'light'].includes(r.id)) continue;
    const S = r.samples, n = S.length, step = 2;
    for (const side of [-1, 1]) {
      let run = [];
      const flush = () => { if (run.length >= 3) { for (let k = 0; k < run.length; k++) { posts.push(run[k]); if (k > 0) rails.push([run[k - 1], run[k]]); } } run = []; };
      for (let i = 0; i < n; i += step) {
        const p = S[i];
        const ox = -p.tz * side, oz = p.tx * side; // outward
        const off = r.halfW + 1.1;
        const x = p.x + ox * off, z = p.z + oz * off;
        const drop = p.y - groundHeight(p.x + ox * (off + 7), p.z + oz * (off + 7));
        const nr = World.roadIndex.nearest(x, z, 12, -1);
        const clear = !nr || nr.ri === World.roads.indexOf(r) || nr.d > World.roads[nr.ri].halfW + 1.5;
        const deckGap = deckLowest(x, z, 4) < groundHeight(x, z) + 4;
        if (drop > 2.2 && clear && !deckGap && Math.hypot(x + 165, z - 420) > 170) run.push({ x, z, y: groundHeight(x, z) });
        else flush();
      }
      flush();
    }
  }
  if (!posts.length) return;
  const wood = new THREE.MeshLambertMaterial({ color: 0x8a6448, flatShading: true });
  const pm = new THREE.InstancedMesh(new THREE.BoxGeometry(0.22, 1.1, 0.22), wood, posts.length);
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), sc = new THREE.Vector3(1, 1, 1), v = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
  posts.forEach((p, k) => { v.set(p.x, p.y + 0.5, p.z); m4.compose(v, q.identity(), sc); pm.setMatrixAt(k, m4); });
  const rm = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 0.2, 0.09), wood, rails.length);
  rails.forEach(([a, b], k) => {
    const dx = b.x - a.x, dz = b.z - a.z, len = Math.hypot(dx, dz), rot = Math.atan2(-dz, dx);
    q.setFromAxisAngle(up, rot); sc.set(len + 0.1, 1, 1);
    const dy = b.y - a.y; const qq = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), Math.atan2(dy, len)); q.multiply(qq);
    v.set((a.x + b.x) / 2, (a.y + b.y) / 2 + 0.8, (a.z + b.z) / 2); m4.compose(v, q, sc); rm.setMatrixAt(k, m4);
    World.colliders.add({ type: 'box', x: (a.x + b.x) / 2, z: (a.z + b.z) / 2, hx: len / 2 + 0.05, hz: 0.12, rot });
  });
  [pm, rm].forEach(m => { m.castShadow = true; m.receiveShadow = true; m.instanceMatrix.needsUpdate = true; m.computeBoundingSphere(); scene.add(m); });
  World.railCount = rails.length;
}

// ============================================================
//  Elevated decks: suspension bridge, canyon viaduct, stunt spiral.
//  Decks are drivable ribbons with their own heights, independent of
//  the terrain, so cars can drive on them, under them, and fall off.
// ============================================================
const Decks = { list: [], grid: null, cs: 10 };

// --- layout -------------------------------------------------------------
// Control points are [x, z, y]; y = 'road' takes the height of the ground road
// the deck starts/ends on (resolved once road heights are known).
const GULL = { x: 700, z: 690, r: 72, plateau: 30 };           // Gull Rock island (new)
const STUNT = { x: 60, z: 190, r: 26, base: 8.0, rise: 32, turns: 2 }; // spiral tower in Golden Meadows

function deckLayout() {
  const defs = [];
  // 1) Gull Rock Bridge: on-ramp off the Coast Highway (NE-bound), curving out over the cliffs,
  //    a 2-tower suspension span to Gull Rock, landing on the island loop road.
  {
    const dir = [GULL.x - 566, GULL.z - 462]; const L = Math.hypot(...dir); const ux = dir[0] / L, uz = dir[1] / L;
    const edge = [GULL.x - ux * (GULL.r - 6), GULL.z - uz * (GULL.r - 6)];
    const land = [GULL.x - ux * 37, GULL.z - uz * 37];
    defs.push({
      id: 'gullbridge', name: 'Gull Rock Bridge', halfW: 5.4, style: 'suspension',
      pts: [[424, 389, 'road'], [446, 377, 'road+0.4'], [474, 365, 18.5], [503, 370, 21.5], [530, 392, 25], [550, 422, 28], [566, 462, 30.5],
        [566 + ux * 60, 462 + uz * 60, 32.5], [566 + ux * L * 0.5, 462 + uz * L * 0.5, 34], [edge[0] - ux * 60, edge[1] - uz * 60, 32.5], [edge[0], edge[1], GULL.plateau + 0.6], [land[0], land[1], 'road']],
      span: { a: [566, 462], b: edge }, endJoin: 'islet',
    });
  }
  // 2) Sky Viaduct: leaves Sunset Canyon Road west of the desert, soars ~38 m over the canyon
  //    on a concrete arch, and rejoins the road near the coast.
  defs.push({
    id: 'skyviaduct', name: 'Sky Viaduct', halfW: 5.0, style: 'viaduct',
    pts: [[190, 256, 'road'], [214, 238, 'road+0.4'], [244, 211, 0], [276, 178, 0], [312, 136, 0], [345, 92, 0], [372, 50, 0],
      [398, 8, 45], [422, -34, 0], [448, -76, 0], [470, -112, 0], [490, -140, 0], [510, -161, 0], [530, -181, 'road+0.5'], [556, -207, 'road']],
    ease: [[1, 7, 1.4], [7, 13, -1.4]], // rounded crest: grades ease to level at the top
    arch: { a: [338, 101], b: [452, -82] },
  });
  // 3) Spiral Jump: spur from Pinecrest Pass into a two-turn spiral, a high straight, a kicker,
  //    a 24 m gap, and a long landing ramp down onto Sunset Canyon Road.
  {
    const C = STUNT, pts = [];
    pts.push([-128, 206, 'road'], [-100, 194, 'g'], [-40, 166, C.base + 0.1], [0, C.z - C.r - 0.5, C.base + 0.1]);
    const n = Math.round(C.turns * 24);
    for (let k = 0; k <= n; k++) { const th = -Math.PI / 2 + k / n * C.turns * TAU; pts.push([C.x + Math.cos(th) * C.r, C.z + Math.sin(th) * C.r, C.base + 0.3 + C.rise * k / n]); }
    const top = C.base + 0.3 + C.rise;
    pts.push([C.x + 30, C.z - C.r, top - 0.6], [C.x + 70, C.z - C.r, top - 2.4], [C.x + 92, C.z - C.r, top - 3.0], [C.x + 100, C.z - C.r, top - 2.0]);
    defs.push({ id: 'spiral', name: 'Spiral Ramp', halfW: 4.6, style: 'stunt', pts, lip: true, helix: C });
    const y0 = top - 6.0, x0 = C.x + 124;
    defs.push({
      id: 'jumpland', name: 'Landing Ramp', halfW: 5.2, style: 'stunt',
      pts: [[x0, C.z - C.r, y0], [x0 + 40, C.z - C.r + 1.5, 0], [x0 + 85, C.z - C.r + 3, 0], [x0 + 128, C.z - C.r + 1, 'g+0.5'], [330, 156, 'road+0.3'], [346, 141, 'road']],
      ease: [0, 3, 1.5], // heights between points 0 and 3: steep at the top, flattening out (follows the fall)
    });
  }
  // 4) Bayou Causeway: a low concrete viaduct over the strait to Gator Bayou (the west island)
  defs.push({
    id: 'bayoucauseway', name: 'Bayou Causeway', halfW: 5.0, style: 'viaduct',
    pts: [[-704, 8, 'road'], [-726, 10, 'road+0.4'], [-760, 14, 6.5], [-800, 19, 7.4], [-842, 24, 6.8], [-878, 28, 'road+0.4'], [-904, 30, 'road']],
  });
  // 5) Frost Bridge: out of the cutting through the north cliffs and over the strait to Frostpeak Isle on a big concrete arch
  defs.push({
    id: 'frostbridge', name: 'Frost Bridge', halfW: 5.2, style: 'viaduct',
    pts: [[34, -706, 'road'], [35, -726, 'road+0.3'], [36, -760, 31.2], [38, -800, 31.8], [39, -840, 31.2], [40, -872, 'road+0.3'], [40, -892, 'road']],
    arch: { a: [36, -745], b: [40, -868] },
  });
  // 6) Cinder Causeway: off the Coast Highway at Bayview's east end, straight out to sea and south to Cinder Isle,
  //    lined up exactly with the Moon's re-entry chute (whose kicker ends just above the junction) so a car flying off
  //    the chute lands on it: low and extra wide over the beach and the shallows (the landing apron), then out over the strait
  {
    const L0 = [-23.1, 483.7], u = [-0.349, 0.937], at = (t) => [L0[0] + u[0] * t, L0[1] + u[1] * t];
    const tEnd = Math.hypot(CINDER_LAND.x - L0[0], CINDER_LAND.z - L0[1]);
    defs.push({
      id: 'cindercauseway', name: 'Cinder Causeway', halfW: 5.0, style: 'viaduct',
      pts: [[...at(33.5), 'road'], [...at(46), 'road+0.3'], [...at(90), 7.6], [...at(150), 7.9], [...at(210), 9.4], [...at(280), 12.6], [...at(340), 13.4], [...at(tEnd - 26), 'road+0.3'], [CINDER_LAND.x, CINDER_LAND.z, 'road']],
      widen: [[0.13, 0.62, 9]],
    });
  }
  // 8) Lava Tube: from the summit terrace at the top of Ember Road into Mount Ember, a corkscrew down round the magma
  //    chamber and out at the foot of the south face (39_volcano.js builds the tube round it)
  defs.push({
    id: 'lavatube', name: 'Lava Tube', halfW: LAVA_TUBE.hw, style: 'lava', under: true, lava: true, tubeDef: LAVA_TUBE, surf: 'road',
    pts: LAVA_TUBE.pts.map((p, i, a) => [p[0], p[1], i === 0 || i === a.length - 1 ? 'road' : p[2]]),
    channel: { flat: LAVA_TUBE.flat, k: LAVA_TUBE.k, rampIn: 18, rampOut: 18 }, bank: { k: 12, max: 0.14 },
    sticky: true, // (the tyres stay on the road: on the corkscrew you get flung up the curved side walls, and you used to bounce off them all the way down)
  });
  // 9) Atlantis (east, v13.4). The Dive Ramp leaves the Coast Highway and plunges under the waves (a bubble gate at the
  //    waterline wraps the car in air); the Crystal Line is an air-filled glass tube round the city; the Grand Canal a
  //    walled channel with a glass roof into the Great Dome; the Skyward Tube climbs back to the surface and the Skyway
  //    Causeway brings you home. (`atl` decks go right down to the seabed; 41_atlantis.js dresses them.)
  {
    const C = ATL_CANAL, cp = (t, y) => [lerp(C.a[0], C.b[0], t), lerp(C.a[1], C.b[1], t), y];
    defs.push({ id: 'diveramp', name: 'Dive Ramp', halfW: 5.5, style: 'viaduct', atl: true,
      pts: [[629, -20, 'road'], [648, -20, 'road+0.2'], [672, -20, 15.0], [700, -20, 11.5], [725, -20, 5.5], [750, -20, -1.5], [775, -20, -9], [800, -20, -16], [825, -20, -23], [850, -21, -29], [875, -22, 'road']] });
    defs.push({ id: 'crystalline', name: 'Crystal Line', halfW: 5.2, style: 'viaduct', atl: true, glass: true, dry: true, noLamps: true,
      pts: [[972, -30, 'road'], [990, -36, -35.2], [1003, -72, -33], [1036, -125, -31], [1092, -162, -30], [1160, -170, -30], [1225, -148, -30.6], [1270, -108, -31.5], [1296, -50, -32.4], [1300, 10, -33.3], [1273.1, 68.4, -34.4], [1243.4, 88.6, -35.6], [1208.4, 81.3, -36.9], [C.a[0], C.a[1], -37.4]] });
    defs.push({ id: 'grandcanal', name: 'Grand Canal', halfW: 7, style: 'viaduct', atl: true, canal: true, dry: true, noLamps: true,
      pts: [cp(0, -37.4), cp(0.33, -37.6), cp(0.66, -37.75), cp(0.85, -37.9), cp(1, -37.95)] });
    defs.push({ id: 'skyward', name: 'Skyward Tube', halfW: 5.2, style: 'viaduct', atl: true, glass: true, dry: true, noLamps: true,
      pts: [[1102, -35, -37.9], [1075, -41, -37.6], [1040, -50, -31], [1000, -60, -22.5], [950, -75, -15], [900, -90, -8.5], [850, -100, -3], [800, -110, 1.5]] });
    defs.push({ id: 'skyway', name: 'Skyway Causeway', halfW: 5.2, style: 'viaduct', atl: true,
      pts: [[800, -110, 1.5], [760, -112, 3.5], [725, -112, 7], [690, -111, 11.5], [655, -110, 'road+0.3'], [622, -109, 'road']] });
  }
  // 7) Emerald Caverns: an underground deck right through Hollow Hill (37_cave.js builds the cave round it).
  //    'under' decks win over the hill above them whenever you're down at their level.
  defs.push({
    id: 'caverns', name: 'Emerald Caverns', halfW: CAVE_DEF.hw, style: 'cave', under: true, cave: true, tubeDef: CAVE_DEF, surf: 'road',
    pts: CAVE_DEF.pts.map((p, i, a) => [p[0], p[1], i === 0 || i === a.length - 1 ? 'road' : p[2]]),
    channel: { flat: CAVE_DEF.flat, k: CAVE_DEF.k, rampIn: 22, rampOut: 22 },
  });
  return defs.concat(skyDeckDefs()); // Sky Highway, Moon bridge/track and re-entry chute (34_sky.js)
}

// --- sampling -----------------------------------------------------------
function deckPathXZ(def) { // planar preview used before heights exist (mesa suppression)
  const v = def.pts.map(p => new THREE.Vector3(p[0], 0, p[1]));
  return new THREE.CatmullRomCurve3(v, false, 'centripetal').getSpacedPoints(Math.max(8, Math.round(new THREE.CatmullRomCurve3(v).getLength() / 4)));
}
function resolveDeckY(p) {
  const y = p[2];
  if (typeof y === 'number') return y;
  if (typeof y === 'function') return y(); // sky decks: heights worked out once the roads (and the Moon) are known
  const m = /^(road|g)([+-][\d.]+)?$/.exec(y); const off = m && m[2] ? parseFloat(m[2]) : 0;
  if (m && m[1] === 'road') { const nr = World.roadIndex.nearest(p[0], p[1], 40); if (nr) return nr.p.y - 0.06 + off; } // matches the flattened road surface
  return World.sampleGrid(World.raw, p[0], p[1]) + off;
}
function buildDeckSamples(defs) {
  Decks.list = defs.map(def => {
    const v = def.pts.map(p => new THREE.Vector3(p[0], resolveDeckY(p), p[1]));
    for (const [a, b, pw] of def.ease ? (Array.isArray(def.ease[0]) ? def.ease : [def.ease]) : []) { // y between two control points follows a power curve over planar distance
      let tot = 0; const acc = [0];
      for (let k = a + 1; k <= b; k++) { tot += Math.hypot(v[k].x - v[k - 1].x, v[k].z - v[k - 1].z); acc.push(tot); }
      for (let k = a + 1; k < b; k++) { const u = acc[k - a] / tot; v[k].y = pw > 0 ? lerp(v[b].y, v[a].y, Math.pow(1 - u, pw)) : lerp(v[a].y, v[b].y, Math.pow(u, -pw)); }
    }
    const curve = new THREE.CatmullRomCurve3(v, false, 'centripetal');
    const len = curve.getLength(), n = Math.max(4, Math.round(len / 2.5));
    const P = curve.getSpacedPoints(n);
    const S = P.map((q, i) => {
      const a = P[Math.max(i - 1, 0)], b = P[Math.min(i + 1, n)];
      let tx = b.x - a.x, tz = b.z - a.z; const l = Math.hypot(tx, tz) || 1;
      return { x: q.x, y: q.y, z: q.z, tx: tx / l, tz: tz / l, s: 0 };
    });
    let s = 0; S.forEach((p, i) => { if (i) s += Math.hypot(p.x - S[i - 1].x, p.y - S[i - 1].y, p.z - S[i - 1].z); p.s = s; });
    if (def.onMoon) for (const p of S) { // a dusty track laid on the Moon, leaning with the curve of the surface
      p.y = moonSurfaceY(p.x, p.z) + 0.07;
      const nx = -p.tz, nz = p.tx; p.bk = (moonSurfaceY(p.x + nx * 2, p.z + nz * 2) - moonSurfaceY(p.x - nx * 2, p.z - nz * 2)) / 4;
    }
    if (def.lip) { // kicker: the last few metres rise more steeply
      const L = def.lip.len || 7, R = def.lip.rise || 0.9;
      for (const p of S) { const d = s - p.s; if (d < L) p.y += R * (def.lip.kick ? (1 - d / L) ** 2 : smooth(L, 0, d)); } // (a kick: steepest right at the end, so it throws you up and out)
    }
    if (def.widen) for (const p of S) { p.hw = def.halfW; for (const [f0, f1, hw] of def.widen) { const s0 = f0 * s, s1 = f1 * s; p.hw = Math.max(p.hw, lerp(def.halfW, hw, smooth(s0 - 25, s0, p.s) * smooth(s1 + 25, s1, p.s))); } }
    if (def.bank) { // banked turns: the outside of a bend is raised (bk = height change per metre of signed lateral)
      const n = S.length, raw = S.map((p, i) => {
        const a = S[Math.max(i - 3, 0)], b = S[Math.min(i + 3, n - 1)], ds = Math.max(b.s - a.s, 1);
        const kn = ((b.tx - a.tx) * -p.tz + (b.tz - a.tz) * p.tx) / ds; // curvature toward the left normal (-tz, tx)
        return clamp(-kn * def.bank.k, -def.bank.max, def.bank.max);
      });
      S.forEach((p, i) => { let t = 0, c = 0; for (let k = -6; k <= 6; k++) { const q = raw[clamp(i + k, 0, n - 1)]; t += q; c++; } p.bk = t / c; });
      if (def.lip) for (const p of S) p.bk *= smooth(0, 20, s - p.s); // kickers stay level
    }
    const boostS = def.boost ? def.boost.map(([a, b, acc]) => { const f = (v) => v < 0 ? s + v : v <= 1 ? v * s : v; return [f(a), f(b), acc]; }) : null;
    if (def.channel && def.channel.rampIn) for (const p of S) p.cw = smooth(0, def.channel.rampIn, p.s) * (def.channel.rampOut ? smooth(s, s - def.channel.rampOut, p.s) : 1); // walls grow in from a flat entry (and out again)
    return { ...def, samples: S, length: s, deck: true, boostS };
  });
  // spatial grid of segments
  const cs = Decks.cs, grid = new Map();
  Decks.list.forEach((d, di) => {
    const S = d.samples;
    for (let i = 0; i < S.length - 1; i++) {
      const a = S[i], b = S[i + 1], r = Math.max(a.hw || d.halfW, b.hw || d.halfW) + 1.5; // (widened stretches, like the Cloud 9 plaza, reach further out)
      const i0 = Math.floor((Math.min(a.x, b.x) - r) / cs), i1 = Math.floor((Math.max(a.x, b.x) + r) / cs);
      const j0 = Math.floor((Math.min(a.z, b.z) - r) / cs), j1 = Math.floor((Math.max(a.z, b.z) + r) / cs);
      for (let ii = i0; ii <= i1; ii++) for (let jj = j0; jj <= j1; jj++) { const k = ii * 100003 + jj; let arr = grid.get(k); if (!arr) { arr = []; grid.set(k, arr); } arr.push(di, i); }
    }
  });
  Decks.grid = grid;
}
// All deck surfaces under (x,z): calls fn(y, deck, segIdx, t, lateral)
function deckHits(x, z, fn, pad = 0) {
  if (!Decks.grid) return;
  const arr = Decks.grid.get(Math.floor(x / Decks.cs) * 100003 + Math.floor(z / Decks.cs)); if (!arr) return;
  let ext = null, inr = null; // tunnels: hits just past a segment's end only count where no segment properly covers the spot
  for (let k = 0; k < arr.length; k += 2) {
    const d = Decks.list[arr[k]], i = arr[k + 1], a = d.samples[i], b = d.samples[i + 1];
    const ex = b.x - a.x, ez = b.z - a.z, L2 = ex * ex + ez * ez || 1;
    let t = ((x - a.x) * ex + (z - a.z) * ez) / L2;
    if (d.under) { // tunnels: measure along the curve, between lines square to the road at each sample (so a car off the centre line on a tight bend sees one smooth surface, not overlapping or gapped segments)
      const Dx = x - a.x, Dz = z - a.z, dtx = b.tx - a.tx, dtz = b.tz - a.tz;
      const c0 = Dx * a.tx + Dz * a.tz, c1 = Dx * dtx + Dz * dtz - (ex * a.tx + ez * a.tz), c2 = -(ex * dtx + ez * dtz);
      const t0 = Math.abs(c1) > 1e-9 ? -c0 / c1 : t, disc = c1 * c1 - 4 * c2 * c0;
      if (Math.abs(c2) > 1e-9 && disc >= 0) { const r = Math.sqrt(disc), t1 = (-c1 + r) / (2 * c2), t2 = (-c1 - r) / (2 * c2); t = Math.abs(t1 - t0) < Math.abs(t2 - t0) ? t1 : t2; } else t = t0;
    }
    const tt = d.under ? 0.4 : 0.02; if (t < -tt || t > 1 + tt) continue; // (the cave's tight bends would leave gaps on the outside of a curve otherwise)
    const px = a.x + ex * t, pz = a.z + ez * t, lat = Math.hypot(x - px, z - pz), tc = clamp(t, 0, 1);
    const hw = a.hw ? a.hw + (b.hw - a.hw) * tc : d.halfW;
    if (lat > hw + 0.15 + pad) continue;
    let y = a.y + (b.y - a.y) * (d.under ? t : tc); // (in a tunnel the ends overlap: carry the slope on past them)
    if (a.bk !== undefined || d.channel) {
      const sl = ((x - px) * -ez + (z - pz) * ex) / Math.sqrt(L2); // signed lateral (+ = left of travel)
      if (a.bk !== undefined) y += (a.bk + (b.bk - a.bk) * tc) * sl;
      if (d.channel) y += deckChannelDy(d, Math.abs(sl)) * (a.cw === undefined ? 1 : a.cw + (b.cw - a.cw) * tc);
    }
    if (d.under) { if (t < 0 || t > 1) { (ext || (ext = [])).push([y, d, i, t, lat]); continue; } (inr || (inr = [])).push(d, y); }
    fn(y, d, i, t, lat);
  }
  // (taking the higher of two overlapping segments made a steep tube a staircase of little steps: you bounced all the way down)
  if (ext) for (const e of ext) { let cov = false; if (inr) for (let k = 0; k < inr.length; k += 2) if (inr[k] === e[1] && Math.abs(inr[k + 1] - e[0]) < 3) cov = true; if (!cov) fn(e[0], e[1], e[2], e[3], e[4]); }
}
// Highest deck surface you could be standing on (not more than `step` above yRef)
function deckAt(x, z, yRef, step = 1.25) {
  let best = null;
  deckHits(x, z, (y, d, i, t) => { if (y <= yRef + step && (!best || y > best.y)) best = { y, deck: d, i, t }; });
  return best;
}
// lowest deck over (x,z); sky decks high above the ground don't count (nothing needs to dodge the Sky Highway)
function deckLowest(x, z, pad = 0) { let lo = Infinity, g = null; deckHits(x, z, (y, d) => { if (d.sky) { if (g === null) g = groundHeight(x, z); if (y - g > 30) return; } if (y < lo) lo = y; }, pad); return lo; }
// bobsled-style channel walls (the re-entry chute): flat floor, then walls curving up to the rim
function deckChannelDy(d, al) { const c = d.channel; return al > c.flat ? c.k * (al - c.flat) * (al - c.flat) : 0; }
function surfaceHeight(x, z, yRef) {
  let g = groundHeight(x, z);
  if (yRef === undefined) return g;
  const m = moonGround(x, z, yRef); if (m > g) g = m;
  const d = deckAt(x, z, yRef);
  return d && (d.y > g || underDeck(d, yRef)) ? d.y : g;
}
// down at the level of an underground deck (the cave), the hill overhead doesn't count
function underDeck(d, yRef) { return d.deck.under && yRef - d.y < (d.deck.tubeDef ? d.deck.tubeDef.size(d.deck.samples[d.i].s).top + 2 : 4); } // (in a tunnel: anywhere below the roof)

// --- terrain interplay ---------------------------------------------------
// Snap deck ends marked 'road' onto the centreline of the road they join, and remember the join
function snapDeckEnds(defs) {
  for (const d of defs) {
    d.joins = [];
    for (const k of [0, d.pts.length - 1]) {
      const p = d.pts[k]; if (typeof p[2] !== 'string' || !p[2].startsWith('road')) continue;
      const nr = World.roadIndex.nearest(p[0], p[1], 45); if (!nr) continue;
      p[0] = nr.p.x; p[1] = nr.p.z; d.joins.push({ end: k ? 'end' : 'start', road: World.roads[nr.ri].id, x: nr.p.x, z: nr.p.z });
    }
  }
}
// planar distance from every terrain grid vertex to the nearest deck centreline (capped), for mesa/peak suppression
function deckDistanceGrid(defs, maxD = 60) {
  const N = W.n, cell = W.cell, half = W.half, out = new Float32Array(N * N).fill(maxD), R = Math.ceil(maxD / cell);
  for (const d of defs) if (!d.sky && !d.under) for (const p of deckPathXZ(d)) {
    const ci = Math.round((p.x + half) / cell), cj = Math.round((p.z + half) / cell);
    for (let jj = Math.max(0, cj - R); jj <= Math.min(N - 1, cj + R); jj++) for (let ii = Math.max(0, ci - R); ii <= Math.min(N - 1, ci + R); ii++) {
      const dd = Math.hypot(-half + ii * cell - p.x, -half + jj * cell - p.z), k = jj * N + ii; if (dd < out[k]) out[k] = dd;
    }
  }
  return out;
}
