  // Googie arch over the launch rail where it leaves Windmill Lane
  const d = Decks.list.find(q2 => q2.id === 'launch'); if (!d) return;
  const p = d.samples[Math.min(d.samples.length - 1, 12)], ag = new THREE.Group(); ag.position.set(p.x, p.y, p.z); ag.rotation.y = Math.atan2(p.tx, p.tz); scene.add(ag);
  const pink = new THREE.MeshLambertMaterial({ color: 0xff4f98 }), cream = new THREE.MeshLambertMaterial({ color: 0xfff4e0 });
  for (const s of [-1, 1]) { const leg = new THREE.Mesh(new THREE.BoxGeometry(1.0, 13, 1.6), pink); leg.position.set(s * 8.4, 6.2, 0); leg.rotation.z = s * 0.12; leg.castShadow = true; ag.add(leg); World.colliders.add({ type: 'circle', x: p.x + Math.cos(ag.rotation.y) * s * 8.4, z: p.z - Math.sin(ag.rotation.y) * s * 8.4, r: 0.9, y0: p.y - 1, y1: p.y + 13 }); }
  const tex = canvasTex(512, 160, (c, w, h) => { c.fillStyle = '#14213d'; c.beginPath(); c.roundRect(4, 4, w - 8, h - 8, 26); c.fill(); c.strokeStyle = '#9fe8ff'; c.lineWidth = 7; c.stroke(); c.fillStyle = '#fff4e0'; c.font = 'bold 66px Arial'; c.textAlign = 'center'; c.fillText('SKY HIGHWAY', w / 2, 84); c.fillStyle = '#ffd166'; c.font = 'bold 34px Arial'; c.fillText('★  TO THE MOON  ★', w / 2, 132); });
  const smat = new THREE.MeshLambertMaterial({ map: tex, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: 0.6 });
  const sign = new THREE.Mesh(new THREE.BoxGeometry(15, 4.6, 0.5), [cream, cream, cream, cream, smat, smat]); sign.position.set(0, 13.4, 0); sign.castShadow = true; ag.add(sign);
