    const dm = Math.hypot(ca.x - MOON.x, ca.y - MOON.y, ca.z - MOON.z), kS = this.kSpace = smooth(MOON.R + 150, MOON.R + 25, dm) * smooth(MOON.y + 10, MOON.y + 70, ca.y);
