    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: { top: { value: new THREE.Color() }, mid: { value: new THREE.Color() }, sunHor: { value: new THREE.Color() }, farHor: { value: new THREE.Color() }, sunDir: { value: new THREE.Vector3(0, 1, 0) }, disc: { value: 1 }, stars: { value: 0 }, moon: { value: 0 } },
