    if (near > 0.3) Rumble.pulse(0.5 * near, 0.9 * near, 900);
    this.burst.forEach((b, i) => { b.t = -Math.random() * 1.6; b.a = Math.random() * TAU; b.sp = 0.7 + Math.random() * 0.6; b.k = i; });
