        World.colliders.add({ type: 'box', x: (p.x + q2.x) / 2 + ox, z: (p.z + q2.z) / 2 + oz, hx: len / 2 + 0.15, hz: 0.3, rot: Math.atan2(-dz, dx), y0: Math.min(p.y, q2.y) - 0.6, y1: Math.max(p.y, q2.y) + Hh });
