      c.strokeStyle = '#fff4e0'; c.fillStyle = '#fff4e0'; c.textAlign = 'center'; c.textBaseline = 'middle';
      for (let v = 0; v <= max + 1e-6; v += step / 2) {
        const a = a0 + (a1 - a0) * v / max, major = Math.abs(v / step - Math.round(v / step)) < 1e-6;
        c.lineWidth = major ? 4 : 2; c.beginPath(); c.moveTo(Math.cos(a) * (r - 4), Math.sin(a) * (r - 4)); c.lineTo(Math.cos(a) * (r - (major ? 18 : 11)), Math.sin(a) * (r - (major ? 18 : 11))); c.stroke();
        if (major) { c.font = `800 ${Math.round(r * 0.2)}px Archivo, Arial`; c.fillText(String(v / (max > 100 ? 1 : 1)), Math.cos(a) * (r - 36), Math.sin(a) * (r - 36)); }
      }
      c.font = `700 ${Math.round(r * 0.13)}px Archivo, Arial`; c.fillStyle = 'rgba(255,244,224,.7)'; c.fillText(label, 0, r * 0.36);
      const a = a0 + (a1 - a0) * clamp(val / max, 0, 1.02);
      c.strokeStyle = '#ff3d8f'; c.lineWidth = 6; c.lineCap = 'round'; c.beginPath(); c.moveTo(-Math.cos(a) * 12, -Math.sin(a) * 12); c.lineTo(Math.cos(a) * (r - 14), Math.sin(a) * (r - 14)); c.stroke();
